import { useActionState } from 'react';

async function updateNameAction(previousState: { name: string }, formData: FormData) {
  const newName = formData.get('name') as string;
  const updatedUser = await fetch('/api/user', { method: 'POST', body: JSON.stringify({ name: newName }) }).then(res => res.json());
  return updatedUser;
}

export function ProfileForm() {
  const [state, formAction, isPending] = useActionState(updateNameAction, { name: 'Alice' });

  return (
    <form action={formAction}>
      <input type="text" name="name" defaultValue={state.name} />
      <button type="submit" disabled={isPending}>Save</button>
    </form>
  );
}

import { useOptimistic, useState } from 'react';

type Message = { id: string; text: string; sending?: boolean };

export function Thread({ messages, sendMessage }: { messages: Message[]; sendMessage: (formData: FormData) => Promise<void> }) {
  const [optimisticMessages, addOptimisticMessage] = useOptimistic(
    messages,
    (state, newMessageText: string) => [
      ...state,
      { id: crypto.randomUUID(), text: newMessageText, sending: true }
    ]
  );

  async function action(formData: FormData) {
    const text = formData.get('message') as string;
    addOptimisticMessage(text);
    await sendMessage(formData);
  }

  return (
    <form action={action}>
      {optimisticMessages.map(msg => (
        <div key={msg.id}>{msg.text} {msg.sending && '(Sending...)'}</div>
      ))}
      <input name="message" required />
      <button type="submit">Send</button>
    </form>
  );
}

import { use, Suspense } from 'react';

interface User { id: string; name: string; }

function UserDetails({ userPromise }: { userPromise: Promise<User> }) {
  // Can unwrap promises directly inside component render
  const user = use(userPromise);
  return <h2>{user.name}</h2>;
}

export function Profile({ userPromise }: { userPromise: Promise<User> }) {
  return (
    <Suspense fallback={<div>Loading user...</div>}>
      <UserDetails userPromise={userPromise} />
    </Suspense>
  );
}

import { ReactNode } from 'react';

// 1. Direct ref as prop (no forwardRef needed)
function CustomInput({ ref, placeholder }: { ref?: React.Ref<HTMLInputElement>; placeholder: string }) {
  return <input ref={ref} placeholder={placeholder} />;
}

// 2. Cleanup function inside callback ref
function AutoFocusInput() {
  return (
    <input
      ref={(node) => {
        if (!node) return;
        node.focus();
        return () => {
          // Optional cleanup executed on unmount/re-bind
          console.log('Element removed from DOM');
        };
      }}
    />
  );
}

